/** 
 * Uses the XPP to grab the opening stream tag and create an active session object. The session to create will depend on the sent namespace. In all cases, the method obtains the opening stream tag, checks for errors, and either creates a session or returns an error and kills the connection. If the connection remains open, the XPP will be set to be ready for the first packet. A call to next() should result in an START_TAG state with the first packet in the stream.
 */
private void createSession() throws UnauthorizedException, XmlPullParserException, IOException {
  XmlPullParser xpp=reader.getXPPParser();
  for (int eventType=xpp.getEventType(); eventType != XmlPullParser.START_TAG; ) {
    eventType=xpp.next();
  }
  if ("jabber:client".equals(xpp.getNamespace(null))) {
    session=ClientSession.createSession(serverName,reader,connection);
  }
 else   if ("jabber:component:accept".equals(xpp.getNamespace(null))) {
    session=ComponentSession.createSession(serverName,reader,connection);
  }
 else {
    Writer writer=connection.getWriter();
    StringBuffer sb=new StringBuffer();
    sb.append("<?xml version='1.0' encoding='");
    sb.append(CHARSET);
    sb.append("'?>");
    sb.append("<stream:error>");
    sb.append("<bad-namespace-prefix xmlns=\"urn:ietf:params:xml:ns:xmpp-streams\"/>");
    sb.append("</stream:error>");
    sb.append("</stream:stream>");
    writer.write(sb.toString());
    writer.flush();
    connection.close();
  }
}
